def xargs(
    cmd: tuple[str, ...],
    varargs: Sequence[str],
    *,
    color: bool = False,
    target_concurrency: int = 1,
    _max_length: int = _get_platform_max_length(),
    **kwargs: Any,
) -> tuple[int, bytes]:
    """A simplified implementation of xargs.

    color: Make a pty if on a platform that supports it
    target_concurrency: Target number of partitions to run concurrently
    """
    import subprocess
    import shlex
    import os
    from typing import Any, Sequence

    def run_cmd_with_pty(cmd: tuple[str, ...), args: Sequence[str]) -> bytes:
        try:
            with subprocess.Popen(cmd, stdin=subprocess.PIPE, stdout=subprocess.PIPE, stderr=subprocess.PIPE, text=True, preexec_fn=os.setpgrp) as proc:
                stdout, stderr = proc.communicate('\n'.join(shlex.split(arg) for arg in args))
                if proc.returncode != 0:
                    raise subprocess.CalledProcessError(proc.returncode, cmd, output=stdout, stderr=stderr)
                return stdout.encode('utf-8')
        except Exception as e:
            return f"Error: {e}".encode('utf-8')

    def run_cmd_without_pty(cmd: tuple[str, ...], args: Sequence[str]) -> bytes:
        try:
            result = subprocess.run([cmd[0], *cmd[1:], *args], capture_output=True, text=True, check=True)
            return result.stdout.encode('utf-8')
        except subprocess.CalledProcessError as e:
            return e.stderr.encode('utf-8')

    if color:
        stdout = run_cmd_with_pty(cmd, varargs)
    else:
        stdout = run_cmd_without_pty(cmd, varargs)

    return (0, stdout)

