def xargs(
        cmd: tuple[str, ...],
        varargs: Sequence[str],
        *,
        color: bool = False,
        target_concurrency: int = 1,
        _max_length: int = _get_platform_max_length(),
        **kwargs: Any,
) -> tuple[int, bytes]:
    """A simplified implementation of xargs.

    color: Make a pty if on a platform that supports it
    target_concurrency: Target number of partitions to run concurrently
    """
    import subprocess
    import shlex
    import os
    import sys
    import textwrap

    def _run_cmd(cmd, args):
        if color and sys.stdout.isatty():
            cmd = shlex.split(cmd)
            env = os.environ.copy()
            env['TERM'] = 'xterm-color'
            process = subprocess.Popen(cmd + args, stdout=subprocess.PIPE, stderr=subprocess.STDOUT, env=env)
        else:
            process = subprocess.Popen(cmd + args, stdout=subprocess.PIPE, stderr=subprocess.STDOUT)
        return process.communicate()

    def _get_max_length():
        if sys.platform.startswith('linux'):
            return 2048
        elif sys.platform.startswith('darwin'):
            return 8192
        else:
            return 2048

    _get_platform_max_length = _get_max_length

    if not cmd:
        raise ValueError("cmd must be a non-empty tuple of strings")

    if not all(isinstance(arg, str) for arg in cmd):
        raise ValueError("cmd must be a tuple of strings")

    if not isinstance(varargs, Sequence) or not all(isinstance(arg, str) for arg in varargs):
        raise ValueError("varargs must be a sequence of strings")

    if not isinstance(color, bool):
        raise ValueError("color must be a boolean")

    if not isinstance(target_concurrency, int) or target_concurrency < 1:
        raise ValueError("target_concurrency must be a positive integer")

    if not isinstance(_max_length, int) or _max_length < 1:
        raise ValueError("_max_length must be a positive integer")

    args = varargs[:]
    results = []

    while args:
        batch = args[:target_concurrency]
        args = args[target_concurrency:]

        processes = [_run_cmd(cmd, batch[i:i + 1]) for i in range(len(batch))]
        for process in processes:
            out, _ = process
            results.append(out)

    combined = b''.join(results)
    return process.returncode, combined
