def minimalBases(classes):
    """Reduce a list of base classes to its ordered minimum equivalent"""

    # Create a graph to represent inheritance relationships
    graph = {cls: set() for cls in classes}
    for cls in classes:
        for base in cls.__bases__:
            if base in graph:
                graph[base].add(cls)

    # Topological sort to find the minimal equivalent base classes
    def dfs(node, visited, stack):
        if node not in visited:
            visited.add(node)
            for neighbor in graph[node]:
                dfs(neighbor, visited, stack)
            stack.append(node)

    visited = set()
    stack = []
    for node in classes:
        dfs(node, visited, stack)

    # The minimal equivalent base classes are the ones that are at the bottom of the stack
    minimal = stack[::-1]
    return minimal

