def minimalBases(classes):
    """Reduce a list of base classes to its ordered minimum equivalent"""

    # Create a dictionary to store the minimum base class for each class
    min_bases = {}

    # Iterate over the list of classes
    for cls in classes:
        # Initialize the minimum base class as the current class
        min_base = cls
        # Iterate over the superclass hierarchy of the current class
        for base in cls.__bases__:
            # If the superclass is in the dictionary, update the minimum base class
            if base in min_bases:
                min_base = min(min_base, min_bases[base], key=classes.index)
        # Store the minimum base class in the dictionary
        min_bases[cls] = min_base

    # Return the ordered list of minimum base classes
    return sorted(min_bases.values(), key=classes.index)
