            if error_type not in context.error:
                context.error[error_type] = error
            elif 'index' in context.error[error_type]:
                context.error[error_type]['index'] += [(idx, context.error[error_type]['index'])]
        else:
            context.error[error_type] = error

        if isinstance(context.value, dict):
            if 'error' in context.value:
                if error_type not in context.value['error']:
                    context.value['error'][error_type] = error
                elif 'index' in context.value['error'][error_type]:
                    context.value['error'][error_type]['index'] += [(idx, context.value['error'][error_type]['index'])]
