            if error_name in subcontext:
                subcontext[error_name]["index"] = error_index
            else:
                subcontext[error_name] = {"index": error_index}
        else:
            subcontext[field] = value

    if hasattr(self, "errors"):
        if "error" not in context.value:
            context.value["error"] = {}
