import re

class ValidationError(Exception):
    def __init__(self, messages):
        self.messages = messages
        super().__init__(self.messages)

def _validate_labels(labels):
    """Check that keys and values in the given labels match against their corresponding
    regular expressions.

    Args:
        labels (dict): the different labels to validate.

    Raises:
        ValidationError: if any of the keys and labels does not match their respective
            regular expression. The error contains as message the list of all errors
            which occurred in the labels. Each element of the list is a dictionary with
            one key-value pair:
            - key: the label key or label value for which an error occurred as string.
            - value: the error message.

            .. code:: python

                # Example:
                labels = {
                    "key1": "valid",
                    "key2": ["invalid"],
                    "$$": "invalid",
                    True: True,
                }
                try:
                    _validate_labels(labels)
                except ValidationError as err:
                    assert err.messages == [
                        {"['invalid']": 'expected string or bytes-like object'},
                        {'$$': "Label key '$$' does not match the regex [...]"},
                        {'True': 'expected string or bytes-like object'},
                        {'True': 'expected string or bytes-like object'},
                    ]
    """
    errors = []

    if not labels:
        return  # No labels to validate

    regex_key = r'^[a-zA-Z_][a-zA-Z0-9_]*$'
    regex_value = r'^[a-zA-Z_][a-zA-Z0-9_]*$'

    for key, value in labels.items():
        if not isinstance(key, str):
            errors.append({str(key): f'expected string or bytes-like object'})
        elif not re.match(regex_key, key):
            errors.append({str(key): f"Label key '{key}' does not match the regex {regex_key}"})

        if isinstance(value, list):
            for val in value:
                if not isinstance(val, str):
                    errors.append({str(val): f'expected string or bytes-like object'})
                elif not re.match(regex_value, val):
                    errors.append({str(val): f"Label value '{val}' does not match the regex {regex_value}"})
        elif not isinstance(value, str):
            errors.append({str(value): f'expected string or bytes-like object'})
        elif not re.match(regex_value, value):
            errors.append({str(value): f"Label value '{value}' does not match the regex {regex_value}"})

    if errors:
        raise ValidationError(errors)
