def validate(self, path):
    """Validate OCFL object at path or pyfs root.

    Returns True if valid (warnings permitted), False otherwise.
    """
    try:
        import os
        import pyfs

        # Check if the path is a valid directory
        if not os.path.isdir(path):
            raise ValueError("Invalid path, must be a directory")

        if path == pyfs.ROOT:
            path = pyfs.get_root_path()

        # Validate OCFL object
        if pyfs.is_ocfl_object(path):
            return pyfs.validate_ocfl_object(path)
        else:
            raise ValueError("The provided path is not an OCFL object")

    except Exception as e:
        print(f"Validation failed: {e}")
        return False

