    except FileExistsError:
        # Handle the case where the directory already exists
        raise OCFLStorageRootExistsException(f"The directory {self.path} already exists.")

    # Step 2: Create the `manifest.json` file
    manifest_path = os.path.join(self.path, 'manifest.json')
    manifest = {
        "inventoryVersion": "1.0",
        "inventoryId": self.id,
        "digestAlgorithm": "sha256",
        "storage": {
            "root": self.path
        },
        "heads": {
            self.id: {
                "manifest": "manifest.json",
            }
        }
    }
    with open(manifest_path, 'w') as f:
        json.dump(manifest, f, indent=4)

    # Step 3: Create the `config.yaml` file
    config_path = os.path.join(self.path, 'config.yaml')
    config = {
        "storage": {
            "root": self.path
        },
        "inventory": {
            "root": self.path
        }
    }
    with open(config_path, 'w') as f:
        yaml.dump(config, f, default_flow_style=False)

    # Step 4: Initialize the inventory directory
