    inventory_path = os.path.join(self.path, 'inventory')
    os.makedirs(inventory_path)

    # Step 5: Create an initial inventory file for the root object
    root_inventory_path = os.path.join(inventory_path, f"{self.id}.json")
    root_inventory = {
        "head": self.id,
        "manifest": {
            "sha256": "0" * 64,
            "size": 0
        }
    }
    with open(root_inventory_path, 'w') as f:
        json.dump(root_inventory, f, indent=4)

    # Step 6: Set the initial head to the root object
    self.head = self.id

    # Step 7: Create the `data` directory
    data_path = os.path.join(self.path, 'data')
    os.makedirs(data_path)

