        if isinstance(left, ruamel.yaml.nodes.MappingNode) and isinstance(right, ruamel.yaml.nodes.MappingNode):
            result = left.__class__(tag=left.tag, value=left.value.copy())
            for key, value in right.value.items():
                if key in result.value:
