        if key.value in seen_keys:
            for i, existing_key_value in enumerate(result):
                if existing_key_value[0].value == key.value:
                    result[i] = (key, merge_two_nodes(existing_key_value[1], value))
                    break
        else:
            seen_keys.add(key.value)
            result.append((key, value))

