def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""

    if not isinstance(commands, (list, tuple)):
        commands = [commands]

    cmd = [commands[0]] + args

    if hide_stderr:
        stderr = subprocess.DEVNULL
    else:
        stderr = subprocess.STDOUT if verbose else subprocess.PIPE

    process = subprocess.Popen(cmd, cwd=cwd, env=env, stdout=subprocess.PIPE, stderr=stderr)

    if verbose:
        for line in process.stdout:
            print(line.decode('utf-8'), end='')

    stdout, stderr = process.communicate()

    if stderr:
        raise subprocess.CalledProcessError(process.returncode, cmd, stderr.decode('utf-8'))

    return stdout.decode('utf-8')
