def load_configurations(config_filenames: List[str], overrides: Dict[str, any] = None, resolve_env: bool = True) -> Tuple[Dict[str, any], List[logging.LogRecord]]:
    """
    Given a sequence of configuration filenames, load and validate each configuration file. Return
    the results as a tuple of: dict of configuration filename to corresponding parsed configuration,
    and sequence of logging.LogRecord instances containing any parse errors.
    """

    if overrides is None:
        overrides = {}

    config_dict = {}
    log_records = []

    for filename in config_filenames:
        try:
            with open(filename, 'r') as file:
                config = file.read()

            try:
                parsed_config = eval(config, globals(), {**overrides, 'resolve_env': resolve_env})
                config_dict[filename] = parsed_config
            except Exception as e:
                error_record = logging.LogRecord(name='config_parser', level=logging.ERROR, pathname=filename, lineno=0, msg=str(e), args=(), exc_info=None)
                log_records.append(error_record)
        except FileNotFoundError:
            error_record = logging.LogRecord(name='config_parser', level=logging.ERROR, pathname=filename, lineno=0, msg=f"Configuration file not found: {filename}", args=(), exc_info=None)
            log_records.append(error_record)

    return config_dict, log_records

