def hist_to_graph(hist, make_value=None, get_coordinate="left",
                  field_names=("x", "y"), scale=None):
    import numpy as np
    from folia.main import Graph, Point

    if make_value is None:
        make_value = lambda bin_value: bin_value

    if get_coordinate not in ("left", "right", "middle"):
        raise ValueError("Invalid value for get_coordinate. Must be 'left', 'right', or 'middle'.")

    if len(field_names) != (2 if make_value.__code__.co_argcount == 1 else 1):
        raise ValueError("The number of field_names must match the dimension of the result.")

    x_data = []
    y_data = []

    if scale is True:
        scale = hist.scale

    for bin_i, bin_value in enumerate(hist.bins):
        if bin_value is None:
            continue

        bin_center = bin_i + 0.5
        bin_width = 1
        bin_left = bin_center - bin_width / 2
        bin_right = bin_center + bin_width / 2

        x_val = bin_left if get_coordinate == "left" else \
               bin_center if get_coordinate == "middle" else \
               bin_right

        y_val = make_value(bin_value)
        if not isinstance(y_val, tuple):
            y_val = (y_val,)

        x_data.append(x_val)
        y_data.append(y_val)

    graph = Graph(field_names=field_names, scale=scale)
    for x, y in zip(x_data, y_data):
        if len(y) == 1:
            graph.add_point(Point(x, y[0]))
        else:
            graph.add_point(Point(x, *y))

    return graph

