def parse_diaspora_webfinger(document: str) -> Dict:
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    import json
    from xml.etree import ElementTree as ET

    try:
        parsed = json.loads(document)
        return parsed
    except json.JSONDecodeError:
        pass

    try:
        root = ET.fromstring(document)
        d = {}
        for elem in root:
            if elem.tag == '{http://docs.oasis-open.org/ns-xri/XRD/1.0}Subject':
                d['Subject'] = elem.text
            elif elem.tag == '{http://docs.oasis-open.org/ns-xri/XRD/1.0}Link':
                attrs = elem.attrib
                if 'rel' in attrs and 'href' in attrs:
                    if 'diaspora-id' in attrs:
                        d['diaspora-id'] = attrs['href']
                    elif 'type' in attrs and attrs['type'] == 'http://schemas.google.com/g/2010/gplus#user':
                        d['url'] = attrs['href']
        return d
    except ET.ParseError:
        raise ValueError("Invalid Diaspora webfinger document")

