def _include_groups(self, parser_dict):
    """Resolves the include dict directive in the spec files. """
    if 'include' not in parser_dict:
        return

    include_dict = parser_dict['include']
    if not isinstance(include_dict, dict):
        raise ValueError("Invalid include directive: not a dictionary")

    for key, value in include_dict.items():
        if key not in self._groups:
            raise ValueError(f"Invalid group key: {key}")

        if not isinstance(value, dict):
            raise ValueError(f"Invalid value for group {key}: not a dictionary")

