    """Resolves the include dict directive in the spec files. """

    if 'include' not in parser_dict:
        return

    include_dirs = parser_dict['include']
    for include_dir in include_dirs:
        # Resolve the path to the include directory
        resolved_path = os.path.abspath(include_dir)

        # Check if the path exists
        if not os.path.exists(resolved_path):
            raise FileNotFoundError(f"The include directory {include_dir} does not exist.")

        # Check if the path is a directory
        if not os.path.isdir(resolved_path):
            raise NotADirectoryError(f"The include path {include_dir} is not a directory.")

        # Walk through the directory and process the include files
        for root, _, files in os.walk(resolved_path):
            for file in files:
                if file.endswith('.cfg'):
                    file_path = os.path.join(root, file)
                    try:
                        with open(file_path, 'r') as f:
                            include_content = f.read()
                            # Process the include content (e.g., update parser_dict)
                            self.update_parser_dict(include_content, root)
